	Scopes:       []string{"openid", "profile", "email"},
	Endpoint: oauth2.Endpoint{
		AuthURL:  "https://provider.com/oauth2/authorize",
		TokenURL: "https://provider.com/oauth2/token",
	},
}

// generateRandomState generates a cryptographically secure random state string.
func generateRandomState() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("failed to generate random state: %w", err)
	}
	return hex.EncodeToString(b), nil
}

// isValidRedirectPath validates that the redirect path is safe and within allowed domains.
func isValidRedirectPath(redirectPath string) bool {
	if redirectPath == "" {
		return false
	}

	// Parse the redirect URL to validate it
	parsedURL, err := url.Parse(redirectPath)
	if err != nil {
		return false
	}

	// Only allow relative paths or specific trusted domains
	if parsedURL.Host != "" {
		// If there's a host, ensure it's our trusted domain
		trustedHosts := []string{"yourapp.com", "www.yourapp.com"}
		isTrusted := false
		for _, host := range trustedHosts {
			if strings.EqualFold(parsedURL.Host, host) {
				isTrusted = true
				break
			}
		}
		if !isTrusted {
			return false
		}
	}

	// Ensure the scheme is https if absolute URL
	if parsedURL.Scheme != "" && parsedURL.Scheme != "https" {
		return false
	}

	// Prevent open redirects by ensuring path doesn't start with // or contain malicious patterns
	path := parsedURL.Path
	if strings.HasPrefix(path, "//") {
		return false
	}

	return true
}

